function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 2 || n > 15) return 'n is a whole number from 2 to 15.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges needs exactly n - 1 roads.';
  const root = Array.from({ length: n + 1 }, (_, i) => i);
  const find = x => { while (root[x] !== x) x = root[x] = root[root[x]]; return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2 || edge.some(c => !Number.isInteger(c) || c < 1 || c > n)) return 'Each road is [u, v] with cities from 1 to n.';
    const [a, b] = edge.map(find);
    if (a === b) return 'The roads must form a tree (no loops or repeated roads).';
    root[a] = b;
  }
  return null;
}

