function countSubgraphsForEachDiameter(n, edges) {
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) {
    graph[u - 1].push(v - 1);
    graph[v - 1].push(u - 1);
  }
  const dist = [];
  for (let start = 0; start < n; start++) {
    const row = new Array(n).fill(-1);
    row[start] = 0;
    const queue = [start];
    for (let head = 0; head < queue.length; head++) {
      const city = queue[head];
      for (const next of graph[city]) {
        if (row[next] === -1) {
          row[next] = row[city] + 1;
          queue.push(next);
        }
      }
    }
    dist.push(row);
  }

  const answer = new Array(n - 1).fill(0);
  for (let mask = 1; mask < (1 << n); mask++) {
    let cities = 0;
    let links = 0;
    let diameter = 0;
    for (let i = 0; i < n; i++) {
      if ((mask & (1 << i)) === 0) continue;
      cities++;
      for (let j = i + 1; j < n; j++) {
        if ((mask & (1 << j)) === 0) continue;
        if (dist[i][j] === 1) links++;
        diameter = Math.max(diameter, dist[i][j]);
      }
    }
    if (cities >= 2 && links === cities - 1) answer[diameter - 1]++;
  }
  return answer;
}

