function countSubgraphsForEachDiameter(n, edges) {
  const graph = Array.from({ length: n + 1 }, () => []);
  for (const [u, v] of edges) { graph[u].push(v); graph[v].push(u); }
  // Breadth-first search that never leaves the chosen set: [farthest city, its distance, cities reached].
  const explore = (inside, start) => {
    const depth = new Map([[start, 0]]);
    const queue = [start];
    let far = start;
    for (let h = 0; h < queue.length; h++) {
      const city = queue[h];
      if (depth.get(city) > depth.get(far)) far = city;
      for (const next of graph[city]) if (inside.has(next) && !depth.has(next)) { depth.set(next, depth.get(city) + 1); queue.push(next); }
    }
    return [far, depth.get(far), queue.length];
  };
  const answer = new Array(n - 1).fill(0);
  for (let mask = 1; mask < (1 << n); mask++) {
    const inside = new Set();
    for (let c = 1; c <= n; c++) if (mask & (1 << (c - 1))) inside.add(c);
    if (inside.size < 2) continue;
    const [first, , reached] = explore(inside, [...inside][0]);
    if (reached !== inside.size) continue;
    // Double sweep: the city farthest from anywhere is one end of a longest path.
    const [, span] = explore(inside, first);
    answer[span - 1]++;
  }
  return answer;
}

