function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(13, 15) : int(2, 8);
  const labels = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = int(0, i);
    [labels[i], labels[j]] = [labels[j], labels[i]];
  }
  const shape = rand();
  const edges = [];
  for (let k = 1; k < n; k++) {
    // Paths, stars and random trees each stress different spans.
    const parent = shape < 0.2 ? k - 1 : shape < 0.35 ? 0 : shape < 0.55 ? Math.max(0, k - 1 - int(0, 2)) : int(0, k - 1);
    edges.push(rand() < 0.5 ? [labels[parent], labels[k]] : [labels[k], labels[parent]]);
  }
  for (let i = edges.length - 1; i > 0; i--) {
    const j = int(0, i);
    [edges[i], edges[j]] = [edges[j], edges[i]];
  }
  return [n, edges];
}
